    "Starting inventory": "Początkowe zasoby",
    "Your first interaction": "Twoja pierwsza interakcja",
    "Every map starts with the starting room. Create it with the button on the left.": "Każda mapa zaczyna się od komnaty startowej. Stwórz ją przyciskiem po lewej.",
    "Pick a tile in the palette and put it on the board; press R to rotate it. For now, place two different tiles: they will be taken out of the box and set up during the game.": "Wybierz kafelek w palecie i połóż go na planszy; naciśnij R, aby go obrócić. Na razie połóż dwa różne kafelki: zostaną wyjęte z pudełka i rozłożone w trakcie gry.",
    "The Hero button (H) sets the starting squares of our adventurers. Select 2 to 4 squares in the starting room.": "Przycisk Bohater (H) ustawia pola startowe naszych poszukiwaczy przygód. Zaznacz od 2 do 4 pól w komnacie startowej.",
    "To reveal the map little by little, we need to create a new room. It appears when an object is used, by programming a trigger that opens a room. Let us try it: click the Object button (O) and pick a door. Then add an “Open a room” trigger.": "Aby odsłaniać mapę krok po kroku, trzeba stworzyć nową komnatę. Pojawia się ona, gdy ktoś użyje obiektu, dzięki zaprogramowaniu wyzwalacza, który otwiera komnatę. Spróbujmy: kliknij przycisk Obiekt (O) i wybierz drzwi. Potem dodaj wyzwalacz „Otwórz komnatę”.",
    "You have created your first interaction with the scenery. In the game, the hero will open the door and release the tiles of the next room. Now, let us fill that room: put a chest in a room and program a trigger that gives items to the players (the other buttons and triggers wait for this).": "Oto twoja pierwsza interakcja z otoczeniem. W grze bohater otworzy drzwi i uwolni kafelki następnej komnaty. Teraz wypełnijmy tę komnatę: postaw skrzynię w komnacie i zaprogramuj wyzwalacz, który daje graczom przedmioty (pozostałe przyciski i wyzwalacze czekają na to).",
    "📂 Import a save of the game (.sav)": "📂 Importuj zapis gry (.sav)",
    "Clear all": "Wyczyść wszystko",
    "Search an item…": "Szukaj przedmiotu…",
    "Only what the party has": "Tylko to, co ma drużyna",
    "skills": "umiejętności",
    "Others": "Inne",
    "Clear the whole starting inventory?": "Wyczyścić całe początkowe zasoby?",
    "Replace the starting inventory with the one of this save?": "Zastąpić początkowe zasoby tymi z tego zapisu?",
    "Imported from the save": "Zaimportowano z zapisu",
    "This file is not a save of the game.": "Ten plik nie jest zapisem gry.",
    "For a party of veterans: what it already holds when the campaign starts, won in earlier battles. The party receives it when the campaign begins. Items come from the Workshop (Items and Weapons tabs), the skills from the Skills tab (or the game’s). The item pools of the generated maps leave out the unique items the party already has, and the game never gives an item twice.": "Dla drużyny weteranów: to, co już posiada na początku kampanii, zdobyte we wcześniejszych bitwach. Drużyna otrzymuje to, gdy kampania się zaczyna. Przedmioty pochodzą z Pracowni (zakładki Przedmioty i Bronie), umiejętności z zakładki Umiejętności (lub z gry). Pule przedmiotów generowanych map pomijają unikatowe przedmioty, które drużyna już ma, a gra nigdy nie daje przedmiotu dwa razy.",
    "Starting gold": "Początkowe złoto",
