    "Click the object to move.": "Kliknij obiekt do przesunięcia.",
    "Click the tile to move (any room).": "Kliknij kafelek do przesunięcia (dowolna komnata).",
    "That one is a marker: click the object itself.": "To jest znacznik: kliknij sam obiekt.",
    "Click a tile (not its marker).": "Kliknij kafelek (nie jego znacznik).",
    "Click the object first.": "Najpierw kliknij obiekt.",
    "Click the tile first.": "Najpierw kliknij kafelek.",
