    "Click the marker: the same tile laid again, where it goes.": "Kliknij znacznik: ten sam kafelek położony ponownie tam, gdzie ma trafić.",
    "Click the marker tile.": "Kliknij kafelek-znacznik.",
    "marker": "znacznik",
    "Move the tile": "Przesuń kafelek",
    "Lays this one as the marker; then click the object whose use moves the tile.": "Kładzie ten jako znacznik; potem kliknij obiekt, którego użycie przesuwa kafelek.",
    "Remove only that tile, keeping objects and monsters": "Usuń tylko ten kafelek, zachowując obiekty i potwory",
    "(keeps what stands on it)": "(zachowuje to, co na nim stoi)",
    "\"{q}\": move tile without a tile": "„{Q}”: przesunięcie kafelka bez kafelka",
