    "\"{q}\": remove tile keeping what stands on it, but the tile is not wholly over an underlay (warning)": "„{Q}”: usunięcie kafelka z zachowaniem tego, co na nim stoi, ale kafelek nie leży w całości nad podłożem (ostrzeżenie)",
