    "Base level": "Poziom bazowy",
    "The arrow shows the way up (R turns it). It climbs from the base level to the next one. From level {n} up it stands on tiles of its base level.": "Strzałka pokazuje drogę w górę (R ją obraca). Prowadzi z poziomu bazowego na następny. Od poziomu {n} w górę stoi na kafelkach swojego poziomu bazowego.",
    "Medium pillar (reaches level {n})": "Średni filar (sięga poziomu {n})",
