    "a column standing on a square": "kolumna stojąca na kwadracie",
    "a column standing on a square; it supports no tile": "kolumna stojąca na kwadracie; nie podtrzymuje żadnego kafelka",
    "it supports no tile": "nie podtrzymuje żadnego kafelka",
    "A floor tile needs no pillars.": "Kafelek podłogi nie potrzebuje filarów.",
    "Move to another room…": "Przenieś do innej komnaty…",
    "None yet: use the Pillar tool on its sockets (level ${p.level} on the ribbon). Allowed here: medium pillar, tall pillar.": "Jeszcze brak: użyj narzędzia Filar na jego gniazdach (poziom ${p.level} na wstążce). Dozwolone tutaj: średni filar, wysoki filar.",
    "None yet: use the Pillar tool on its sockets (level ${p.level} on the ribbon). Allowed here: short pillar, medium pillar, tall pillar.": "Jeszcze brak: użyj narzędzia Filar na jego gniazdach (poziom ${p.level} na wstążce). Dozwolone tutaj: niski filar, średni filar, wysoki filar.",
    "None yet: use the Pillar tool on its sockets (level ${p.level} on the ribbon). Allowed here: tall pillar.": "Jeszcze brak: użyj narzędzia Filar na jego gniazdach (poziom ${p.level} na wstążce). Dozwolone tutaj: wysoki filar.",
    "Pillars of this tile": "Filary tego kafelka",
    "Room {n}: tile {n}A is elevated (level {n}) with no pillars.": "Komnata {n}: kafelek {n}A jest podwyższony (poziom {n}) i nie ma filarów.",
    "Room {n}: tile {n}A is elevated with no pillars (warning)": "Komnata {n}: kafelek {n}A jest podwyższony i nie ma filarów (ostrzeżenie)",
    "Tile {n}A": "Kafelek {n}A",
