    "Music, scene, spawn pool, final mission, intro": "Muzyka, scena, pula wystawiania, ostateczna misja, wstęp",
    "Name": "Nazwa",
    "New rooms are born from an object: select it, add the trigger “{q}”. Pick a room here before touching what is in it.": "Nowe komnaty rodzą się z obiektu: zaznacz go, dodaj wyzwalacz „{Q}”. Wybierz tu komnatę, zanim dotkniesz tego, co w niej jest.",
    "Room {n}: tile {n}B is elevated (level {n}) with no pillars.": "Komnata {n}: kafelek {n}B jest podwyższony (poziom {n}) i nie ma filarów.",
