    "Visible from the start. The map introduction, music and final mission are in": "Widoczna od początku. Wstęp, muzykę i ostateczną misję mapy znajdziesz w oknie",
    "click a dim one to add it for this room only.": "kliknij przygaszonego, aby dodać go tylko dla tej komnaty.",
    "click to put in or take out": "kliknij, aby dodać lub wyjąć",
