    "). Which monster of the pool enters is drawn in the game.": "). To, który potwór z puli wejdzie, losuje gra.",
    "+ Another space": "+ Kolejne pole",
    "Intensity of this room": "Intensywność tej komnaty",
    "Tier range {n}–{n}, campaign progression {n} (": "Zakres rang {n}–{n}, postęp kampanii {n} (",
    "What the game would do": "Co zrobiłaby gra",
    "When the group is defeated": "Gdy grupa zostanie pokonana",
    "When the room starts, the game fills these spaces with its own rule for random spawns: points = intensity ÷ {n} × heroes × {n} × progression; it takes the highest tier of the map’s range the points pay for (costs {n}, {n}, {n}, {n}, {n}, {n}…), and monsters of the pool that have that tier enter, one per space (up to {n}), while the points last. Leftover points go to the next balanced room. All may enter, or just one strong monster.": "Gdy komnata się zaczyna, gra wypełnia te pola według własnej zasady losowego wystawiania: punkty = intensywność ÷ {n} × bohaterowie × {n} × postęp; bierze najwyższą rangę z zakresu mapy, na którą starczy punktów (koszty {n}, {n}, {n}, {n}, {n}, {n}…), a potwory z puli, które mają tę rangę, wchodzą po jednym na pole (do {n}), dopóki starcza punktów. Pozostałe punkty przechodzą na następną zrównoważoną komnatę. Mogą wejść wszystkie albo tylko jeden silny potwór.",
    "change": "zmień",
    "it takes the highest tier of the map’s range the points pay for (costs {n}, {n}, {n}, {n}, {n}, {n}…), and monsters of the pool that have that tier enter, one per space (up to {n}), while the points last. Leftover points go to the next balanced room. All may enter, or just one strong monster.": "bierze najwyższą rangę z zakresu mapy, na którą starczy punktów (koszty {n}, {n}, {n}, {n}, {n}, {n}…), a potwory z puli, które mają tę rangę, wchodzą po jednym na pole (do {n}), dopóki starcza punktów. Pozostałe punkty przechodzą na następną zrównoważoną komnatę. Mogą wejść wszystkie albo tylko jeden silny potwór.",
    "{n} (= spaces, default)": "{n} (= pola, domyślnie)",
    "{n} balanced space in this room": "Zrównoważone pola w tej komnacie: {n}",
    "{n} hero": "Bohaterowie: {n}",
    "{n} monster, tier {n} (too few points: the minimum)": "Potwory: {n}, ranga {n} (za mało punktów: minimum)",
    "Opened by:": "Otwierana przez:",
    "Remove this room": "Usuń tę komnatę",
    "Text when revealed": "Tekst przy odsłonięciu",
    "Text after the room is set up": "Tekst po przygotowaniu komnaty",
    "Text after the board is set up": "Tekst po przygotowaniu planszy",
    "What the heroes find in it: a person, an object (the interaction tokens)": "Co bohaterowie w niej znajdują: osobę, obiekt (żetony interakcji)",
    "Tile {n} is in another room: reusing it here needs that room removed first": "Kafelek {n} jest w innej komnacie: aby użyć go tutaj, trzeba najpierw usunąć tamtą komnatę",
    "give one an “{q}” trigger": "daj jednemu z nich wyzwalacz „{Q}”",
    "no object opens this room; give one an “{q}” trigger": "żaden obiekt nie otwiera tej komnaty; daj jednemu z nich wyzwalacz „{Q}”",
    "no tiles; no object opens this room": "brak kafelków; żaden obiekt nie otwiera tej komnaty",
    "Go to that room": "Przejdź do tej komnaty",
    "Open a room": "Otwórz komnatę",
    "Opens": "Otwiera",
    "a new room can be created here too.": "tu można też stworzyć nową komnatę.",
    "opened by “{q}”": "otwierana przez „{Q}”",
    "A scene (dialogue boxes)": "Scena (ramki dialogowe)",
    "A scene of dialogue boxes (like the story flow), your own film full screen, a sound effect of the game or your own sound file. (a scene, a video, a sound)": "Scena z ramkami dialogowymi (jak przebieg fabuły), twój własny film na pełnym ekranie, efekt dźwiękowy z gry albo twój własny plik dźwiękowy. (scena, wideo, dźwięk)",
    "A sound (game effect or your own file)": "Dźwięk (efekt z gry lub własny plik)",
    "A tile": "Kafelek",
    "A video (your own film)": "Wideo (twój własny film)",
    "Add / Remove…": "Dodaj / Usuń…",
    "Add a trigger to “{q}”": "Dodaj wyzwalacz do „{Q}”",
    "Add or remove?": "Dodać czy usunąć?",
    "Add what?": "Co dodać?",
    "Adds to (or removes from) the item pool or the monster spawn pool of the map, for the rest of the map. (item, monster spawn)": "Dodaje do puli przedmiotów lub puli wystawiania potworów mapy (albo z nich usuwa), na resztę mapy. (przedmiot, wystawianie potworów)",
    "Add…": "Dodaj…",
