    "Change item / spawn pool": "Zmień pulę przedmiotów / wystawiania",
    "Change which pool?": "Którą pulę zmienić?",
    "Monster spawn": "Wystawianie potworów",
    "Play a scene, video or sound": "Odtwórz scenę, wideo lub dźwięk",
    "Play what?": "Co odtworzyć?",
    "Puts something on the board, or takes it off, during play: tiles, objects, monsters, rooms. (a tile, an object, spawn monsters, a tile, a room, an object, a monster)": "Kładzie coś na planszy lub z niej zdejmuje w trakcie gry: kafelki, obiekty, potwory, komnaty. (kafelek, obiekt, wystaw potwory, kafelek, komnata, obiekt, potwór)",
    "Remove…": "Usuń…",
    "Something appears on the board: a tile, an object or monsters. (a tile, an object, spawn monsters)": "Coś pojawia się na planszy: kafelek, obiekt lub potwory. (kafelek, obiekt, wystaw potwory)",
    "Takes something off the board: a tile, a room, an object or monsters. (a tile, a room, an object, a monster)": "Zdejmuje coś z planszy: kafelek, komnatę, obiekt lub potwory. (kafelek, komnata, obiekt, potwór)",
    "What happens when a hero uses this object. Several triggers run in order.": "Co się dzieje, gdy bohater używa tego obiektu. Kilka wyzwalaczy działa po kolei.",
    "Puts something on the board, or takes it off, during play: tiles, objects, monsters, rooms. (a tile, an object, a tile, a room, an object, a monster)": "Kładzie coś na planszy lub z niej zdejmuje w trakcie gry: kafelki, obiekty, potwory, komnaty. (kafelek, obiekt, kafelek, komnata, obiekt, potwór)",
    "What happens once, when the count reaches {n} (the total of the counter). Several triggers run in order.": "Co dzieje się raz, gdy licznik osiągnie {n} (sumę licznika). Kilka wyzwalaczy działa po kolei.",
    "When the balanced group is defeated: “{q}”": "Gdy zrównoważona grupa zostanie pokonana: „{Q}”",
    "A goal on this map, announced when the monster is defeated and listed with the objectives. An objective does not end the map: the mission does (Map setup). An objective can be chosen there as the mission.": "Cel na tej mapie, ogłaszany po pokonaniu potwora i wymieniany wśród zadań. Zadanie nie kończy mapy: kończy ją misja (Ustawienia mapy). Tam można wybrać zadanie jako misję.",
    "From when the monster is defeated, the round counter runs the triggers inside: every N rounds (as many times as you say, or to the end of the map), or once, N rounds later. For a wave, put “{q}” inside: the spawn has its own “{q}”.": "Od momentu pokonania potwora licznik rund uruchamia wyzwalacze wewnątrz: co N rund (tyle razy, ile wskażesz, albo do końca mapy) lub raz, N rund później. Dla fali umieść w środku „{Q}”: wystawianie ma własne „{Q}”.",
    "When this monster is defeated: “{q}”": "Gdy ten potwór zostanie pokonany: „{Q}”",
    "If the test fails: “{q}”": "Jeśli test się nie powiedzie: „{Q}”",
