    "Takes one tile off the board with everything on it (objects, pillars, monsters). Frees it for reuse in a later room.": "Zdejmuje jeden kafelek z planszy ze wszystkim, co na nim jest (obiekty, filary, potwory). Zwalnia go do ponownego użycia w późniejszej komnacie.",
