    "Delete the category": "Usuń kategorię",
    "Empty: pick it in the sheet of a weapon or of a new part.": "Pusta: wybierz ją w arkuszu broni lub nowej części.",
    "New category": "Nowa kategoria",
    "No category": "Bez kategorii",
    "By kind": "Według rodzaju",
    "By category": "Według kategorii",
    "Category": "Kategoria",
    "Only to organise the Workshop (Weapons tab → By category); nothing changes in the game.": "Tylko do porządkowania Pracowni (zakładka Bronie → Według kategorii); w grze nic się nie zmienia.",
    "New hafts of the workshop": "Nowe drzewca z Pracowni",
    "New grips of the workshop": "Nowe rękojeści z Pracowni",
    "A new haft of the workshop for this weapon: an item the party gets from a trigger or crafts with a recipe": "Nowe drzewce z Pracowni dla tej broni: przedmiot, który drużyna dostaje z wyzwalacza lub wytwarza według receptury",
    "A new grip of the workshop for this weapon: an item the party gets from a trigger or crafts with a recipe": "Nowa rękojeść z Pracowni dla tej broni: przedmiot, który drużyna dostaje z wyzwalacza lub wytwarza według receptury",
    "None yet (“{q}” above). A new haft is an item: the party gets it from a “{q}” trigger or crafts it with a recipe, and fits it in the armory.": "Jeszcze brak („{Q}” powyżej). Nowe drzewce to przedmiot: drużyna dostaje je z wyzwalacza „{Q}” lub wytwarza według receptury i montuje w zbrojowni.",
    "None yet (“{q}” above). A new grip is an item: the party gets it from a “{q}” trigger or crafts it with a recipe, and fits it in the armory.": "Jeszcze brak („{Q}” powyżej). Nowa rękojeść to przedmiot: drużyna dostaje ją z wyzwalacza „{Q}” lub wytwarza według receptury i montuje w zbrojowni.",
    "+ New haft": "+ Nowe drzewce",
