    "A choice in the campaign": "Wybór w kampanii",
    "A counter of the map (see the “{q}” trigger, or the Counts button on the ribbon) must have reached a number: {n} keys found, all the seals broken…": "Licznik mapy (patrz wyzwalacz „{Q}” lub przycisk Liczniki na wstążce) musi osiągnąć określoną liczbę: znalezione klucze ({n}), złamane wszystkie pieczęcie…",
