    "Requirement for “{q}” of “{q}”": "Wymaganie dla „{Q}” w „{Q}”",
    "Some other object of the map must have been used first (click it).": "Jakiś inny obiekt mapy musi zostać użyty wcześniej (kliknij go).",
    "Something the party chose earlier in the campaign (an answer ticked “{q}”): or that it did not choose.": "Coś, co drużyna wybrała wcześniej w kampanii (odpowiedź z zaznaczonym „{Q}”), albo czego nie wybrała.",
    "The party has an item": "Drużyna ma przedmiot",
    "This trigger runs only when every requirement holds": "Ten wyzwalacz działa tylko wtedy, gdy wszystkie wymagania są spełnione",
    "This trigger runs only when every requirement holds; the other triggers of “{q}” are not held back. When one fails, the “{q}” triggers of this box run instead.": "Ten wyzwalacz działa tylko wtedy, gdy wszystkie wymagania są spełnione; pozostałe wyzwalacze „{Q}” nie są wstrzymywane. Gdy któreś nie jest spełnione, zamiast tego działają wyzwalacze „{Q}” tej ramki.",
    "the other triggers of “{q}” are not held back. When one fails, the “{q}” triggers of this box run instead.": "pozostałe wyzwalacze „{Q}” nie są wstrzymywane. Gdy któreś nie jest spełnione, zamiast tego działają wyzwalacze „{Q}” tej ramki.",
