    "If it fails": "Jeśli nie jest spełnione",
    "Only in a campaign: start one (top bar) and remember answers in its scenes.": "Tylko w kampanii: rozpocznij ją (górny pasek) i zapamiętuj odpowiedzi w jej scenach.",
    "Only when its requirement holds": "Tylko gdy jego wymaganie jest spełnione",
    "reaches": "osiąga",
    "the other triggers are not held back.": "pozostałe wyzwalacze nie są wstrzymywane.",
    "Campaign screen": "Ekran kampanii",
    "That map stays off the world map until this trigger runs": "Ta mapa nie pojawia się na mapie świata, dopóki ten wyzwalacz nie zadziała",
    "then it appears as soon as the cards before it in the story flow are completed.": "potem pojawia się, gdy tylko zostaną ukończone poprzedzające ją karty przebiegu fabuły.",
    "Counter “{q}”": "Licznik „{Q}”",
    "Counts…": "Liczniki…",
    "Nothing happens when the count is complete.": "Nic się nie dzieje, gdy licznik się zapełni.",
    "Starts at {n}": "Zaczyna od {n}",
    "Starts at {n}; total {n}.": "Zaczyna od {n}; suma {n}.",
    "What happens once, when the count reaches {n}: open the way, give a reward, show a text…": "Co dzieje się raz, gdy licznik osiągnie {n}: otwiera drogę, daje nagrodę, pokazuje tekst…",
    "total {n}.": "suma {n}.",
    "+ New counter": "+ Nowy licznik",
    "+ Trigger": "+ Wyzwalacz",
    "An objective of the map: completed when the count reaches {n}": "Zadanie mapy: wypełnione, gdy licznik osiągnie {n}",
    "Changed by": "Zmieniany przez",
    "Consequence": "Skutek",
    "Counters keep a number during the map: keys found, levers pulled, seals broken… They live only in the app (nothing goes to the inventory). Triggers add to them or take from them; when a count reaches its total, its map objective is completed and its consequence runs (once). A counter can also count by itself the monsters defeated or the rounds passed.": "Liczniki przechowują liczbę w trakcie mapy: znalezione klucze, pociągnięte dźwignie, złamane pieczęcie… Istnieją tylko w aplikacji (nic nie trafia do zasobów). Wyzwalacze do nich dodają lub z nich odejmują; gdy licznik osiągnie swoją sumę, jego zadanie mapy zostaje wypełnione, a jego skutek działa (raz). Licznik może też sam liczyć pokonane potwory lub minione rundy.",
    "Map objective": "Zadanie mapy",
    "Monsters defeated": "Pokonane potwory",
    "New counter (Keys, Levers, Seals…)": "Nowy licznik (Klucze, Dźwignie, Pieczęcie…)",
    "Rename: every trigger and requirement that uses it follows": "Zmień nazwę: każdy wyzwalacz i wymaganie, które go używa, podąża za zmianą",
    "Required / used by": "Wymagany / używany przez",
    "Rounds passed": "Minione rundy",
    "Starts at": "Zaczyna od",
    "Total": "Suma",
    "Triggers: only the “{q}” triggers change it. Monsters defeated or rounds passed: it also adds {n} by itself": "Wyzwalacze: zmieniają go tylko wyzwalacze „{Q}”. Pokonane potwory lub minione rundy: dodaje też sam {n}",
    "Used by {n} trigger(s) or requirement(s): they lose the counter": "Używany przez wyzwalacze lub wymagania (liczba: {n}): tracą licznik",
    "What happens once, when the count reaches {n}": "Co dzieje się raz, gdy licznik osiągnie {n}",
    "[total] in the messages, the objective and the consequence. Empty: what the “{q}” triggers add up to": "[total] w komunikatach, zadaniu i skutku. Puste: suma tego, co dodają wyzwalacze „{Q}”",
    "nothing yet: give an object (or a monster) an “{q}” trigger, or make it count monsters defeated or rounds passed": "jeszcze nic: daj obiektowi (lub potworowi) wyzwalacz „{Q}” albo każ mu liczyć pokonane potwory lub minione rundy",
    "requires {n}": "wymaga {n}",
    "when a count reaches its total, its map objective is completed and its consequence runs (once). A counter can also count by itself the monsters defeated or the rounds passed.": "gdy licznik osiągnie swoją sumę, jego zadanie mapy zostaje wypełnione, a jego skutek działa (raz). Licznik może też sam liczyć pokonane potwory lub minione rundy.",
    "(Ogg Vorbis) is the format that suits the game best": "(Ogg Vorbis) to format, który najlepiej pasuje do gry",
    "(Ogg Vorbis) is the format that suits the game best; WAV and MP{n} also work. The file is saved next to the map file in the Bigorna\\Mapas folder (the same folder as the .bmap).": "(Ogg Vorbis) to format, który najlepiej pasuje do gry; WAV i MP{n} też działają. Plik jest zapisywany obok pliku mapy w folderze Bigorna\\Mapas (tym samym folderze co .bmap).",
    "+ add an item…": "+ dodaj przedmiot…",
    "Add music (OGG, WAV, MP{n})…": "Dodaj muzykę (OGG, WAV, MP{n})…",
    "All workshop items": "Wszystkie przedmioty z Pracowni",
    "All workshop monsters ({n})": "Wszystkie potwory z Pracowni ({n})",
