    "Default text if empty": "Domyślny tekst, jeśli puste",
    "Defeat every monster (default)": "Pokonaj wszystkie potwory (domyślnie)",
    "Defeat the monsters of a room": "Pokonaj potwory komnaty",
    "Description (in the map list)": "Opis (na liście map)",
