    "Item pool": "Pula przedmiotów",
    "Items (and materials) the heroes may get in this map. The “{q}” trigger draws from it: a random item (never the same twice, nor one the party already has), or random materials worth N loot points. Edited in the Workshop too.": "Przedmioty (i surowce), które bohaterowie mogą zdobyć na tej mapie. Wyzwalacz „{Q}” losuje z niej: losowy przedmiot (nigdy ten sam dwa razy ani taki, który drużyna już ma) albo losowe surowce warte N punktów łupu. Edytowana także w Pracowni.",
    "Lowest tier": "Najniższa ranga",
