    "Room {n} ({n} monster(s))": "Komnata {n} (potwory: {n})",
    "Round limit (defeat when reached)": "Limit rund (porażka po osiągnięciu)",
    "Sets the points of the balanced spaces: points = intensity of the room ÷ {n} × heroes × {n} × progression (the intensity is set on a balanced space, {n} to {n}). The game's quest {n} uses {n} and each quest adds {n}.": "Ustala punkty zrównoważonych pól: punkty = intensywność komnaty ÷ {n} × bohaterowie × {n} × postęp (intensywność ustawia się na zrównoważonym polu, od {n} do {n}). Misja gry {n} używa {n}, a każda misja dodaje {n}.",
    "Survive N rounds": "Przetrwaj N rund",
    "Text shown for the mission": "Tekst pokazywany dla misji",
    "The final mission needs an object (Map setup).": "Ostateczna misja wymaga obiektu (Ustawienia mapy).",
    "The objective is announced when its trigger fires": "Zadanie jest ogłaszane, gdy jego wyzwalacz zadziała",
    "The tiers the game picks from (its default is {n} to {n}": "Rangi, z których wybiera gra (domyślnie od {n} do {n}",
    "The tiers the game picks from (its default is {n} to {n}; quest {n} stays at {n}).": "Rangi, z których wybiera gra (domyślnie od {n} do {n}; misja {n} zostaje przy {n}).",
    "Use a specific object (click it)": "Użyj konkretnego obiektu (kliknij go)",
    "WAV and MP{n} also work. The file is saved next to the map file in the Bigorna\\Mapas folder (the same folder as the .bmap).": "WAV i MP{n} też działają. Plik jest zapisywany obok pliku mapy w folderze Bigorna\\Mapas (tym samym folderze co .bmap).",
    "What the monsters and the rewards of this map draw from, and how hard the game's rule makes the “{q}” spaces.": "Z czego losują potwory i nagrody tej mapy oraz jak trudne według zasady gry są pola „{Q}”.",
    "Your own music for this map, played in a loop in place of the game’s.": "Twoja własna muzyka do tej mapy, odtwarzana w pętli zamiast muzyki gry.",
    "as the mission, completing it ends the map.": "jako misja, jego wypełnienie kończy mapę.",
    "empty": "puste",
    "in the game, “{q}” lists it.": "w grze „{Q}” go wyświetla.",
    "quest {n} stays at {n}).": "misja {n} zostaje przy {n}).",
    "writes the .bmap into the folder chosen in ⚙ (the game’s Bigorna\\Mapas)": "zapisuje plik .bmap w folderze wybranym w ⚙ (Bigorna\\Mapas gry)",
    "writes the .bmap into the folder chosen in ⚙ (the game’s Bigorna\\Mapas); in the game, “{q}” lists it.": "zapisuje plik .bmap w folderze wybranym w ⚙ (Bigorna\\Mapas gry); w grze „{Q}” go wyświetla.",
    "{n} = no limit": "{n} = bez limitu",
    "(H/W): only on the Heroic and Warfare difficulties": "(B/W): tylko na poziomach trudności Bohaterski i Wojna",
    "(H/W): the weakness or resistance counts only on the Heroic and Warfare difficulties, like the game's own ({n} of its monsters have a resistance like that).": "(B/W): podatność lub odporność liczy się tylko na poziomach trudności Bohaterski i Wojna, tak jak w samej grze ({n} jej potworów ma taką odporność).",
    "(for example the head, the haft and the grip). The app adds up what each part gives: damage, damage types, abilities and the chance of each ability.": "(na przykład głowica, drzewce i rękojeść). Aplikacja sumuje to, co daje każda część: obrażenia, rodzaje obrażeń, zdolności i szansę każdej zdolności.",
    "(nothing yet)": "(jeszcze nic)",
    "(nothing)": "(nic)",
    "(optional, shown in bold before the rules, like “{q}”)": "(opcjonalnie, pokazywane pogrubione przed zasadami, jak „{Q}”)",
    "(optional, shown in italics before the activation)": "(opcjonalnie, pokazywane kursywą przed aktywacją)",
    "(read aloud, shown in italics)": "(czytane na głos, pokazywane kursywą)",
    "(the rules)": "(zasady)",
    "+ A recipe for it": "+ Receptura na to",
