    ", part": ", część",
    ": part": ": część",
    ": pick a weapon, open one of its parts and change it, or create a new part for one of the three places. The weapon itself only keeps its name.": ": wybierz broń, otwórz jedną z jej części i zmień ją albo stwórz nową część dla jednego z trzech miejsc. Sama broń zachowuje tylko swoją nazwę.",
    "A change applies while this map is played, to every copy of the part, also the ones bought or found later.": "Zmiana obowiązuje podczas rozgrywania tej mapy, dla każdego egzemplarza części, także tych kupionych lub znalezionych później.",
    "A different monster each time": "Za każdym razem inny potwór",
    "A feat is a goal a hero pursues during the quests (attack with a spear {n} times, open {n} chests…). The game counts it by itself and gives the reward when it is done. Import the game’s feats (they stay as in the game; duplicate one to change it), or write new ones for any hero.": "Wyzwanie to cel, do którego bohater dąży w trakcie misji (zaatakuj włócznią {n} razy, otwórz {n} skrzynie…). Gra sama je liczy i daje nagrodę po jego wykonaniu. Zaimportuj wyzwania z gry (pozostają jak w grze; zduplikuj jedno, aby je zmienić) albo napisz nowe dla dowolnego bohatera.",
    "A new head of the workshop for this weapon: an item the party gets from a trigger or crafts with a recipe": "Nowa głowica z Pracowni dla tej broni: przedmiot, który drużyna dostaje z wyzwalacza lub wytwarza według receptury",
    "A new weapon in its place": "Nowa broń na jej miejscu",
    "A recipe says what an item costs in crafting materials when the heroes craft it in the camp. Import the game’s recipes to change their costs, or write one for an item of the workshop. The party learns a recipe from a “{q}” trigger, or knows it from the start.": "Receptura określa, ile surowców kosztuje przedmiot, gdy bohaterowie wytwarzają go w obozie. Zaimportuj receptury z gry, aby zmienić ich koszty, albo napisz recepturę dla przedmiotu z Pracowni. Drużyna poznaje recepturę z wyzwalacza „{Q}” albo zna ją od początku.",
    "A skill card is unlocked for the hero (the physical card at the table)": "Karta umiejętności zostaje odblokowana dla bohatera (fizyczna karta przy stole)",
    "A skill card is unlocked for the hero (the physical card at the table); a recipe is learned by the party.": "Karta umiejętności zostaje odblokowana dla bohatera (fizyczna karta przy stole); drużyna poznaje recepturę.",
    "A workshop tile is your own physical piece: once per room, reusing it in another room asks to remove the earlier one, and it takes pillars in its sockets (between two squares on a straight edge) when elevated. In the app the mod builds it as a flat tile of this shape, with your picture or colour, and the heroes walk on it like on any tile.": "Kafelek z Pracowni to twój własny fizyczny element: raz na komnatę, ponowne użycie w innej komnacie prosi o usunięcie wcześniejszego, a gdy jest podwyższony, przyjmuje filary w swoich gniazdach (między dwoma kwadratami na prostej krawędzi). W aplikacji mod buduje go jako płaski kafelek o tym kształcie, z twoim obrazem lub kolorem, a bohaterowie chodzą po nim jak po każdym kafelku.",
