    "Each weapon has one hero in the game (its parts, the shop, the inventory and the feats follow it). Picking the weapon of another hero hands him this one in exchange. The numbers come from the weapons: they are changed in the Weapons tab. The weapons belong to the profile: they stay with it if the hero leaves.": "Każda broń ma w grze jednego bohatera (jej części, targowisko, zasoby i wyzwania podążają za nim). Wybranie broni innego bohatera oddaje mu w zamian tę. Wartości pochodzą z broni: zmienia się je w zakładce Bronie. Bronie należą do profilu: zostają z nim, jeśli bohater odejdzie.",
