    "Drag the pieces to put the weapon together as you want it": "Przeciągaj elementy, aby złożyć broń tak, jak chcesz",
    "Drag the pieces to put the weapon together as you want it; the wheel (or the slider) changes the size of the chosen piece, Shift+wheel, Q/E or the turn slider rotate it, the arrows nudge it. A piece only shows inside its own box: what goes out of it is cut (shown faint).": "Przeciągaj elementy, aby złożyć broń tak, jak chcesz; kółko (lub suwak) zmienia rozmiar wybranego elementu, Shift+kółko, Q/E lub suwak obrotu go obracają, strzałki go przesuwają. Element widać tylko wewnątrz jego własnej ramki: to, co z niej wychodzi, jest przycinane (pokazane blado).",
    "Drag the pieces to put the weapon together, forge the template and bake the pictures": "Przeciągaj elementy, aby złożyć broń, wykuj szablon i wypal obrazy",
    "Duplicate": "Duplikuj",
    "Each sheet changes one of the six heroes of the game while this map is played: name, portrait and animated figure. Their weapons are in the Weapons tab. What you leave as it is stays as in the game.": "Każdy arkusz zmienia jednego z sześciu bohaterów gry podczas rozgrywania tej mapy: imię, portret i animowaną figurkę. Ich bronie są w zakładce Bronie. To, czego nie ruszysz, pozostaje jak w grze.",
