    "Pick a kind of weapon, then its heads, hafts or grips. What you change applies while this map is played (to every copy of the part, also the ones bought or found later)": "Wybierz rodzaj broni, a potem jej głowice, drzewca lub rękojeści. To, co zmienisz, obowiązuje podczas rozgrywania tej mapy (dla każdego egzemplarza części, także tych kupionych lub znalezionych później)",
    "Pick a kind of weapon, then its heads, hafts or grips. What you change applies while this map is played (to every copy of the part, also the ones bought or found later); what you leave stays as in the game.": "Wybierz rodzaj broni, a potem jej głowice, drzewca lub rękojeści. To, co zmienisz, obowiązuje podczas rozgrywania tej mapy (dla każdego egzemplarza części, także tych kupionych lub znalezionych później); to, czego nie ruszysz, pozostaje jak w grze.",
