    "Write plain text. The buttons put in the names the app fills in ([monster] = the name of this monster, [hero] = the name of the hero it targets (or another name the app fills in)) and the game icons. Rule words like scar, terrify or focus become the game’s highlighted terms by themselves.": "Pisz zwykłym tekstem. Przyciski wstawiają nazwy, które uzupełnia aplikacja ([monster] = nazwa tego potwora, [hero] = imię bohatera, w którego celuje (lub inna nazwa, którą uzupełnia aplikacja)), oraz ikony gry. Słowa zasad, takie jak blizna, przerażenie czy skupienie, same stają się wyróżnionymi terminami gry.",
