    "Boxes of “{q}”: drag from a box’s ● (or an answer’s ●) onto another box to say what comes next": "Ramki „{Q}”: przeciągnij od ● ramki (lub od ● odpowiedzi) na inną ramkę, aby wskazać, co nastąpi dalej",
    "Boxes play in the order of the arrows, starting at the first. A question box branches: each answer leads to its own next box. A video box plays your own film (MP{n} or WebM) between the other boxes.": "Ramki odtwarzają się w kolejności strzałek, zaczynając od pierwszej. Ramka pytania rozgałęzia się: każda odpowiedź prowadzi do własnej następnej ramki. Ramka wideo odtwarza twój własny film (MP{n} lub WebM) pomiędzy innymi ramkami.",
