    "Every map, side quest and waypoint has a place here and a marker kind: main quest, side quest, narrative event or city visit.": "Każda mapa, misja poboczna i punkt trasy ma tu swoje miejsce i rodzaj znacznika: misja główna, misja poboczna, wydarzenie fabularne lub wizyta w mieście.",
    "Everything of this campaign is erased from the editor, and it cannot be undone:": "Wszystko z tej kampanii zostanie wymazane z edytora i nie da się tego cofnąć:",
