    "Files already exported stay in the folder; delete them there if you want. Autosave stops following this campaign, so it will not erase them. The game keeps the progress of any party that played it.": "Już wyeksportowane pliki zostają w folderze; usuń je tam, jeśli chcesz. Autozapis przestaje śledzić tę kampanię, więc ich nie wymaże. Gra zachowuje postępy każdej drużyny, która w nią grała.",
