    "PNG or JPG, {n}:{n} ({n}×{n} fits exactly). It covers the whole frame the game shows": "PNG lub JPG, {n}:{n} ({n}×{n} pasuje idealnie). Pokrywa cały kadr pokazywany przez grę",
    "PNG or JPG, {n}:{n} ({n}×{n} fits exactly). It covers the whole frame the game shows; the game's water, burnt land, place names and roads are hidden. The mist covers a fixed region of the game's own map (the Mistlands).": "PNG lub JPG, {n}:{n} ({n}×{n} pasuje idealnie). Pokrywa cały kadr pokazywany przez grę; woda, spalona ziemia, nazwy miejsc i drogi z gry są ukryte. Mgła pokrywa stały obszar mapy samej gry (Mgliste Krainy).",
    "Place this waypoint on the world map": "Umieść ten punkt trasy na mapie świata",
    "Plays as": "Odtwarza się jako",
    "Point at a line to light its arrow. To see where a card leads, click its ●.": "Wskaż linię, aby podświetlić jej strzałkę. Aby zobaczyć, dokąd prowadzi karta, kliknij jej ●.",
