    "Stay and fill them": "Zostań i wypełnij je",
    "Story flow": "Przebieg fabuły",
    "The choices the campaign remembers from one map to the next: spared the bandit, sided with the rebels, took the cursed ring… A choice is set when the party picks an answer ticked “{q}” (or by a “{q}” action) and stays for the rest of the campaign. Cards of the story flow and triggers of the maps can then happen only if the party made it, or did not.": "Wybory, które kampania pamięta z jednej mapy na następną: oszczędzono bandytę, poparto buntowników, zabrano przeklęty pierścień… Wybór zostaje ustawiony, gdy drużyna wybierze odpowiedź z zaznaczonym „{Q}” (albo przez akcję „{Q}”), i obowiązuje do końca kampanii. Karty przebiegu fabuły i wyzwalacze map mogą wtedy zadziałać tylko wtedy, gdy drużyna dokonała tego wyboru (albo gdy go nie dokonała).",
    "The party moves on the world map (it goes after the selected card)": "Drużyna przesuwa się po mapie świata (trafia za zaznaczoną kartę)",
    "The scene goes on with the next box when the film ends.": "Scena przechodzi do następnej ramki, gdy film się skończy.",
    "Then:": "Następnie:",
    "They are exported as they are. Fill them, or delete the ones you do not need.": "Są eksportowane w obecnym stanie. Wypełnij je albo usuń te, których nie potrzebujesz.",
    "Type the name of the campaign to confirm:": "Wpisz nazwę kampanii, aby potwierdzić:",
