    "World map": "Mapa świata",
    "World map position: -{n}, {n}.": "Położenie na mapie świata: -{n}, {n}.",
    "World map position: {n}, {n}.": "Położenie na mapie świata: {n}, {n}.",
    "Write the boxes of this scene": "Napisz ramki tej sceny",
