    "Writes the .bcamp and its maps (download), then deletes.": "Zapisuje plik .bcamp i jego mapy (pobieranie), potem usuwa.",
    "You are building the rooms of this map. Pick another map, or add maps, waypoints and dialogues, on the campaign screen (“{q}” above).": "Budujesz komnaty tej mapy. Wybierz inną mapę albo dodaj mapy, punkty trasy i dialogi na ekranie kampanii („{Q}” powyżej).",
    "after Map {n}": "po Mapie {n}",
