    "narrator": "narrator",
    "nothing depends on it yet: pick it in “{q}” of a card, or as the requirement “{q}” of a map trigger.": "nic jeszcze od niej nie zależy: wybierz ją w „{Q}” karty albo jako wymaganie „{Q}” wyzwalacza mapy.",
    "nothing sets it yet: tick “{q}” in a question box and give it this name. Until then “{q}” is never true.": "nic jej jeszcze nie ustawia: zaznacz „{Q}” w ramce pytania i nadaj jej tę nazwę. Do tego czasu „{Q}” nigdy nie jest prawdą.",
    "only a question may branch": "rozgałęziać może tylko pytanie",
    "progression {n}": "postęp {n}",
    "question": "pytanie",
    "the name is yours.": "nazwa należy do ciebie.",
    "the scenes that follow it play in the same visit.": "sceny, które po niej następują, odtwarzają się podczas tej samej wizyty.",
    "the story flow: {n} card(s), {n} scene(s) with their boxes, {n} story variable(s)": "przebieg fabuły: karty: {n}, sceny z ramkami: {n}, zmienne fabularne: {n}",
    "the workshop: {n} monster(s), {n} NPC(s), {n} item(s), {n} hero(es), {n} weapon(s), {n} recipe(s), {n} feat(s), {n} tile(s)/object(s) of your own": "Pracownia: potwory: {n}, BN: {n}, przedmioty: {n}, bohaterowie: {n}, bronie: {n}, receptury: {n}, wyzwania: {n}, własne kafelki/obiekty: {n}",
    "the world map positions, the rewards, the music and videos chosen": "położenia na mapie świata, nagrody, wybrana muzyka i wideo",
    "with your own map picture, draw the roads on the left": "z własnym obrazem mapy rysuj drogi po lewej",
    "without a name": "bez nazwy",
    "{n} box(es): text, questions and videos (your own films), played one after the other in the same frame. Played at this point of the story: after a map it is the map’s closing scene": "Ramki ({n}): tekst, pytania i wideo (twoje własne filmy), odtwarzane jedno po drugim w tym samym kadrze. Odtwarzane w tym punkcie fabuły: po mapie to scena zamykająca mapę",
    "{n} box(es): text, questions and videos (your own films), played one after the other in the same frame. Played at this point of the story: after a map it is the map’s closing scene; after a waypoint it plays on arrival; before anything it opens the campaign.": "Ramki ({n}): tekst, pytania i wideo (twoje własne filmy), odtwarzane jedno po drugim w tym samym kadrze. Odtwarzane w tym punkcie fabuły: po mapie to scena zamykająca mapę; po punkcie trasy odtwarza się po przybyciu; na samym początku otwiera kampanię.",
    "{n} room(s)": "Komnaty: {n}",
