    "Original maps": "Oryginalne mapy",
    "The original maps of the game are read by the Bigorna mod from your own copy of the game: start the game once with the mod installed (the title screen prepares them), then open the editor from the Editor folder of the game again.": "Oryginalne mapy gry są odczytywane przez mod Bigorna z twojego własnego egzemplarza gry: uruchom grę raz z zainstalowanym modem (ekran tytułowy je przygotowuje), a potem ponownie otwórz edytor z folderu Editor gry.",
    "The quests of the game, converted into maps of the editor: tiles, objects, rooms, monsters and the logic the triggers can say.": "Misje z gry, przekształcone w mapy edytora: kafelki, obiekty, komnaty, potwory i logika, którą potrafią wyrazić wyzwalacze.",
    "Each map comes with notes on what was simplified (Map setup).": "Każda mapa ma notatki o tym, co uproszczono (Ustawienia mapy).",
