    "This erases everything the editor keeps: the map or campaign on screen, the Workshop (monsters, items, materials, objects, imported or made), the packages (in the app: the Pacotes folder, every package in it), the pictures kept by the editor, the quick save, your archetypes, the hints and warnings, window positions and sizes, the author, the export folder and the autosave.": "To wymaże wszystko, co przechowuje edytor: mapę lub kampanię na ekranie, Pracownię (potwory, przedmioty, surowce, obiekty, zaimportowane lub zrobione), paczki (w aplikacji: folder Pacotes, każda paczka w nim), obrazy przechowywane przez edytor, szybki zapis, twoje archetypy, podpowiedzi i ostrzeżenia, położenie i rozmiary okien, autora, folder eksportu i autozapis.",
    "Reset everything: the work on screen, the Workshop and the packages, the pictures kept, the quick save, archetypes, tips and warnings, window positions and sizes, author, export folder and autosave. The language stays.": "Resetuje wszystko: pracę na ekranie, Pracownię i paczki, przechowywane obrazy, szybki zapis, archetypy, porady i ostrzeżenia, położenie i rozmiary okien, autora, folder eksportu i autozapis. Język zostaje.",
