    "Each item gained counts one.": "Każdy zdobyty przedmiot liczy się jako jeden.",
    "A round counts once when it happens that many times in it.": "Runda liczy się raz, gdy zdarzy się to w niej tyle razy.",
    "It must happen every round; from that round in a row on, each round counts one.": "Musi się zdarzać w każdej rundzie; każda kolejna taka runda z rzędu dolicza jeden.",
    "Each time counts one.": "Każdy raz liczy się jako jeden.",
    "The damage of each attack is added up.": "Obrażenia każdego ataku są sumowane.",
    "4. When the game offers it": "4. Kiedy gra to proponuje",
    "The game offers each hero two feats at a time, drawn among the ones available. A feat becomes available from its act and once the hero has completed that many feats of their own (0: from the start). The game spreads its own in steps: 0, 4, 8, 12 and 14.": "Gra proponuje każdemu bohaterowi po dwa wyzwania naraz, losowane spośród dostępnych. Wyzwanie staje się dostępne od swojego aktu i gdy bohater wykona tyle własnych wyzwań (0: od początku). Gra rozkłada własne wyzwania stopniami: 0, 4, 8, 12 i 14.",
    "5. Reward": "5. Nagroda",
    "Taken out (the game does not check them at this moment):": "Pominięte (gra nie sprawdza ich w tym momencie):",
    "Size, position and mirror of the picture": "Rozmiar, położenie i odbicie obrazu",
    "Adjust": "Dopasuj",
    "Adjust the picture": "Dopasuj obraz",
    "Mirror (flip left to right)": "Odbij (od lewej do prawej)",
    "Whole picture": "Cały obraz",
    "Fill the frame": "Wypełnij kadr",
    "Drag the picture to move it; the wheel or the slider changes its size; the arrows nudge it. What is outside the frame shows faint and is cut.": "Przeciągnij obraz, aby go przesunąć; kółko lub suwak zmienia jego rozmiar; strzałki go przesuwają. To, co jest poza kadrem, jest pokazane blado i przycinane.",
    "Drag the picture to move it; the wheel or the slider changes its size; the arrows nudge it. What is outside the circle shows faint and is cut.": "Przeciągnij obraz, aby go przesunąć; kółko lub suwak zmienia jego rozmiar; strzałki go przesuwają. To, co jest poza okręgiem, jest pokazane blado i przycinane.",
    "Made from the picture of the monster (below): ✎ Adjust fits it in the portrait.": "Zrobiony z obrazu potwora (poniżej): ✎ Dopasuj umieszcza go w portrecie.",
    "Made from the picture of the hero (below): ✎ Adjust fits it in the portrait.": "Zrobiony z obrazu bohatera (poniżej): ✎ Dopasuj umieszcza go w portrecie.",
    "A picture of its own for the card.": "Własny obraz dla karty.",
    "The picture of the monster (above), standing on the board.": "Obraz potwora (powyżej), stojący na planszy.",
    "Another picture for the card": "Inny obraz dla karty",
    "Use the monster’s picture": "Użyj obrazu potwora",
    "No picture to adjust.": "Brak obrazu do dopasowania.",
    "Could not open this picture.": "Nie udało się otworzyć tego obrazu.",
    "Centre": "Wyśrodkuj",
