    "new weapon": "nowa broń",
    "box fixed": "ramka ustalona",
    "A new weapon has one part of each: its stats are on the right (✎ Stats).": "Nowa broń ma po jednej części każdego rodzaju: jej statystyki są po prawej (✎ Statystyki).",
    "Pick the parts in the middle column; ✎ Stats changes the damage, the ability and the rest of each one.": "Wybierz części w środkowej kolumnie; ✎ Statystyki zmienia obrażenia, zdolność i resztę każdej z nich.",
    "Language of the map (its flag shows in the community library)": "Język mapy (jego flaga widnieje w bibliotece społeczności)",
