    "Remove this exit": "Usuń to wyjście",
    "Pick a condition: without one, this exit never happens.": "Wybierz warunek: bez niego to wyjście nigdy nie nastąpi.",
    "The story goes on by the first exit whose condition holds, checked from the top. When none holds, it goes on by “In any other case”. Once a card after it has played, the way taken stays for the rest of the campaign.": "Fabuła idzie przez pierwsze wyjście, którego warunek jest spełniony, sprawdzając od góry. Gdy żaden nie jest, idzie przez „W każdym innym przypadku”. Gdy karta za nim zostanie rozegrana, wybrana droga zostaje do końca kampanii.",
    "An exit can also be linked on the canvas: drag from the ● of the Crossroads onto a card.": "Wyjście można też połączyć na płótnie: przeciągnij z ● Rozdroża na kartę.",
    "A tie counts as the highest: in a Crossroads, the first exit that holds wins.": "Remis liczy się jako najwyższa: na Rozdrożu wygrywa pierwsze spełnione wyjście.",
